#!/usr/bin/env node
// Build the Supplemental Catalog Synthesis module (typed contracts 1.0) through the SDK compiler.
//
// One translation unit: the SDS $OMM headers (object API, generated by scripts/lib/sds-cpp-headers.mjs from the
// spacedatastandards.org package this module pins, or SPACE_DATA_STANDARDS_ROOT), the repository's SHA-256
// (files/orbit-products/src/sha256.hpp, read in place), the compiled default of config/provider-gate-status.json as
// C++ tables (generated here: the module parses no JSON), and src/catalog_synthesis.cpp. The SDK compiler stages the
// runtime types (TimerTick, IngestRequest, FlowNotice, HostOps) and typedHostcall.hpp.
//
//   node build.mjs
//
// Output: dist/isomorphic/module.wasm (browser and wasmedge; storage_query, timers), dist/guest-link/,
// dist/plugin-manifest.json, dist/build-provenance.json.
import fs from "node:fs/promises";
import path from "node:path";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import createFlatc from "flatc-wasm/module";
import { compileModuleFromSource } from "space-data-module-sdk/compiler";
import { generateSdsHeaders } from "../../scripts/lib/sds-cpp-headers.mjs";
import { assertArtifactThreadModel } from "../../scripts/lib/thread-model.mjs";

// THREAD MODEL - declared, never inferred (scripts/lib/thread-model.mjs): one pass on the calling thread, nothing
// spawned.
const THREAD_MODEL = "single-thread";

const root = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(root, "../..");
const read = async (file) => (await fs.readFile(file, "utf8")).replace(/^#pragma once\s*$/gm, "");

// The compiled gate default: config/provider-gate-status.json as C++ string tables.
const gate = JSON.parse(await fs.readFile(path.join(root, "config/provider-gate-status.json"), "utf8"));
const lit = (s) => JSON.stringify(String(s));
const providers = Object.entries(gate.providers ?? {});
const spacetrack = gate.spacetrackSourceNames ?? [];
const gateTables = [
  "// Generated by build.mjs from config/provider-gate-status.json.",
  `static const char* const kGateProviders[][2] = {${providers.map(([p, l]) => `{${lit(p)}, ${lit(l)}}`).join(", ") || '{"", ""}'}};`,
  `static const size_t kGateProviderCount = ${providers.length};`,
  `static const char* const kGateSpacetrack[] = {${spacetrack.map(lit).join(", ") || '""'}};`,
  `static const size_t kGateSpacetrackCount = ${spacetrack.length};`,
  `static const char* const kGateDefaultLevel = ${lit(gate.defaultLevelForUnlistedProvider ?? "interim")};`,
].join("\n");

const { header, version, families } = await generateSdsHeaders(["OMM"], import.meta.url, createFlatc);
const sourceCode = [
  "#include <cstddef>",
  header,
  await read(path.join(repo, "files/orbit-products/src/sha256.hpp")),
  gateTables,
  await read(path.join(root, "src/catalog_synthesis.cpp")),
].join("\n\n");

const manifestPath = path.join(root, "plugin-manifest.json");
const manifest = JSON.parse(await fs.readFile(manifestPath, "utf8"));
const distRoot = path.join(root, "dist");
await fs.rm(distRoot, { recursive: true, force: true });
const outputPath = path.join(distRoot, "isomorphic/module.wasm");
await fs.mkdir(path.dirname(outputPath), { recursive: true });

const compilation = await compileModuleFromSource({
  manifest,
  sourceCode,
  language: "c++",
  outputPath,
  threadModel: THREAD_MODEL,
  // The sync space_data_module_host hostcall bridge (plugin.getConfig, storage.query); resolved at instantiation.
  allowUndefinedImports: true,
});
if (!compilation.report?.ok) throw new Error(`SDK validation failed:\n${JSON.stringify(compilation.report?.issues ?? [], null, 2)}`);
assertArtifactThreadModel(outputPath, THREAD_MODEL, "analysis/catalog-synthesis");

const guestLinkDir = path.join(distRoot, "guest-link");
await fs.mkdir(guestLinkDir, { recursive: true });
await fs.writeFile(path.join(guestLinkDir, "module-link.o"), compilation.guestLink.objectBytes);
const { format, language, threadModel, symbolPrefix, methodSymbols } = compilation.guestLink;
await fs.writeFile(path.join(guestLinkDir, "metadata.json"), `${JSON.stringify({
  version: 1, format, language, threadModel, symbolPrefix, methodSymbols, capabilities: manifest.capabilities,
}, null, 2)}\n`);
await fs.copyFile(manifestPath, path.join(distRoot, "plugin-manifest.json"));
const wasm = await fs.readFile(outputPath);
await fs.writeFile(path.join(distRoot, "build-provenance.json"), `${JSON.stringify({
  spacedatastandards: version, sdsFamilies: families, gateStatusVersion: gate.version ?? null, threadModel: THREAD_MODEL,
  wasmSha256: createHash("sha256").update(wasm).digest("hex"),
}, null, 2)}\n`);
console.log(`Built ${path.relative(root, outputPath)} (${wasm.length} bytes) against spacedatastandards.org@${version}`);
